/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Every status the closed group does not cover. `status=open` expands to these. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

export const ISSUE_STATUS_GROUPS = ["open", "closed"] as const;

export type IssueStatusGroup = (typeof ISSUE_STATUS_GROUPS)[number];

/** A status chip or the `open` / `closed` group names the filter vocabulary accepts. */
export type IssueStatusFilter = IssueStatus | IssueStatusGroup;

/** Expands `open` and `closed` to their members and drops anything else. */
export function expandIssueStatuses(
  values: readonly string[],
): IssueStatus[] {
  const seen = new Set<IssueStatus>();
  for (const value of values) {
    const members: readonly IssueStatus[] =
      value === "open"
        ? OPEN_ISSUE_STATUSES
        : value === "closed"
          ? CLOSED_ISSUE_STATUSES
          : ISSUE_STATUSES.includes(value as IssueStatus)
            ? [value as IssueStatus]
            : [];
    for (const status of members) seen.add(status);
  }
  return ISSUE_STATUSES.filter((status) => seen.has(status));
}

