export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

/** A concrete status or one of the groups `open` and `closed`. */
export const issueStatusFilterSchema = z.union([
  issueStatusSchema,
  z.enum(["open", "closed"]),
]);

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** `YYYY-MM-DD` (UTC calendar day) or a full ISO-8601 timestamp. */
export const dueBeforeSchema = z.union([
  z.string().refine(isCalendarDate, "expected a YYYY-MM-DD date"),
  isoTimestampSchema,
]);

/** User id, `"me"`, or — for assignees — `"none"` / null meaning unassigned. */
export const assigneeFilterSchema = z
  .union([z.literal("me"), z.literal("none"), userIdSchema, z.null()])
  .transform((value) => (value === "none" ? null : value));

export const authorFilterSchema = z.union([z.literal("me"), userIdSchema]);

