const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Exclusive upper bound: the UTC instant the calendar day ends. */
function endOfUtcDay(value: string): string {
  const match = CALENDAR_DATE.exec(value);
  if (match === null) return value;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  return new Date(Date.UTC(year, month - 1, day + 1)).toISOString();
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const archivedOnly = input.archivedOnly === true;
  // `only` lists archived rows alone; `includeArchived` mixes them in.
  // `shouldFilterArchived` stays the single decision for the live predicate.
  const scope: ArchiveScope =
    archivedOnly || !shouldFilterArchived(input)
      ? { includeArchived: true }
      : {};
  const statuses =
    input.status === undefined ? [] : expandIssueStatuses(input.status);
  const labelIds =
    input.labelIds === undefined ? [] : [...new Set(input.labelIds)];

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    livePredicate(issues.archivedAt, scope),
    archivedOnly ? isNotNull(issues.archivedAt) : undefined,
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    statuses.length === 0 ? undefined : inArray(issues.status, statuses),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `undefined` is "anyone"; `null` is the unassigned sentinel.
    input.assigneeId === undefined
      ? undefined
      : input.assigneeId === null
        ? isNull(issues.assigneeId)
        : eq(issues.assigneeId, input.assigneeId),
    input.authorId === undefined
      ? undefined
      : eq(issues.authorId, input.authorId),
    input.dueBefore === undefined
      ? undefined
      : and(
          isNotNull(issues.dueAt),
          lt(
            issues.dueAt,
            CALENDAR_DATE.test(input.dueBefore)
              ? endOfUtcDay(input.dueBefore)
              : input.dueBefore,
          ),
        ),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    labelIds.length === 0
      ? undefined
      : and(
          ...labelIds.map(
            (labelId) =>
              sql`exists (
                select 1 from ${issueLabels}
                where ${issueLabels.issueId} = ${issues.id}
                  and ${issueLabels.orgId} = ${input.orgId}
                  and ${issueLabels.labelId} = ${labelId}
              )`,
          ),
        ),
  );
}

